/** Cut every packed sprite back into a texture of its own old key. Skips any already there. */
export function buildPackedSprites(scene) {
    let built = 0;
    for (const sheet of PACKED_SHEETS) {
        if (!scene?.textures?.exists?.(sheet.key)) continue;
        for (const { key, frame, width, height } of sheet.entries) {
            if (scene.textures.exists(key)) continue;
            const texture = scene.textures.createCanvas(key, width, height);
            texture.drawFrame(sheet.key, frame, 0, 0);
            texture.refresh();
            built++;
        }
    }
    return built;
}
